#include <string>
#include <utility>  // For std::move, though not directly used here

class StrVec {
public:
    // Constructor
    StrVec(): elements(nullptr), first_free(nullptr), cap(nullptr) {}  // Initialize pointers to null

    // Destructor - Rule of Three
    ~StrVec() {
        free();  // Custom function to delete memory
    }

    // Copy Constructor - Rule of Three
    StrVec(const StrVec& other) {
        auto newData = alloc_n_copy(other.elements, other.first_free);
        elements = newData.first;
        first_free = cap = newData.second;
    }

    // Copy Assignment Operator - Rule of Three
    StrVec& operator=(const StrVec& other) {
        if (this != &other) {  // Check for self-assignment
            auto newData = alloc_n_copy(other.elements, other.first_free);
            free();  // Free existing resources
            elements = newData.first;
            first_free = cap = newData.second;
        }
        return *this;
    }

private:
    std::allocator<std::string> alloc;  // Allocator for strings
    std::string* elements;  // Pointer to the first element
    std::string* first_free;  // Pointer to the first free element
    std::string* cap;  // Pointer to one past the end of allocated memory

    std::pair<std::string*, std::string*> alloc_n_copy(const std::string* b, const std::string* e) {
        // Allocate and copy elements (simplified)
        auto data = alloc.allocate(e - b);
        return {data, std::uninitialized_copy(b, e, data)};
    }

    void free() {
        if (elements) {
            for (auto p = first_free; p != elements; )
                alloc.destroy(--p);
            alloc.deallocate(elements, cap - elements);
        }
    }
};
